SET NAMES 'utf8';
INSERT  IGNORE INTO `locales_questgiver_greeting` VALUES (234,0,NULL,NULL,NULL,'西部荒野中滋生了一股邪恶的腐败气息。当我在洛丹伦的战场上履行职责时，这些诚实的农场被匪徒和杀人犯侵占，变成了他们的藏身之处。人民军需要你的帮助。',NULL,NULL,NULL,NULL),(235,0,NULL,NULL,NULL,'欢迎来到我们简陋的家！总是很高兴看到友善的面孔。你的胳膊真强壮。我丈夫和我一直在找帮手来打理农场。现在大多数好人都离开了，很难找到能干的人来帮忙。',NULL,NULL,NULL,NULL),(237,0,NULL,NULL,NULL,'这些地方除了麻烦还是麻烦。我试着告诉那个傻瓜索尔丹趁早离开，但他就是不听。但我可不是傻瓜。我和薇娜一修好这辆马车就马上离开这里。',NULL,NULL,NULL,NULL),(238,0,NULL,NULL,NULL,'有时我觉得天上有一朵巨大的乌云，不停地给我们降下厄运。首先，我们被赶出了自己的土地，现在我们甚至无法离开西部荒野。一切都乱套了。必须做点什么。',NULL,NULL,NULL,NULL),(239,0,NULL,NULL,NULL,'冒险来自远近四方$b与奇特的旅人会面相谈$b但若你想向我请教问题$b必须先完成一个简单的任务！',NULL,NULL,NULL,NULL),(240,0,NULL,NULL,NULL,'唉，没有这些新麻烦出现的时候，维持这里的秩序就已经够难的了！我希望你带来的是好消息，$N……',NULL,NULL,NULL,NULL),(241,0,NULL,NULL,NULL,'嘿，朋友。我叫雷米。$B我从东边的赤脊山来，来这儿找生意做。你有什么……有什么生意吗？？',NULL,NULL,NULL,NULL),(253,0,NULL,NULL,NULL,'啊哈！日安，日安，$C先生！来，坐下喝一杯。你眼中闪烁着进取的光芒，我想你会发现和我交谈是值得的……',NULL,NULL,NULL,NULL),(261,0,NULL,NULL,NULL,'你好，市民。你看起来像是一个有目标的人——你和暴风城军队有事务要办吗？',NULL,NULL,NULL,NULL),(264,0,NULL,NULL,NULL,'稍息，$c。如果你只是路过，我建议你沿着大路走，只在白天赶路。如果你在夜色镇有事，考虑把你的能力借给守夜人。我们的技巧无可置疑，但我们的人数太少了。',NULL,NULL,NULL,NULL),(265,0,NULL,NULL,NULL,'我早已感知到你的到来，$n。它早已写在了星辰的轨迹之中。',NULL,NULL,NULL,NULL),(267,0,NULL,NULL,NULL,'欢迎来到夜色镇。办事员达尔特为您服务。我能帮您什么忙吗？',NULL,NULL,NULL,NULL),(272,0,NULL,NULL,NULL,'你好，你好！欢迎来到我的厨房，先生/女士！这里出产血色乌鸦酒馆所有最精美的佳肴。啊，光是闻到这香气就令人心旷神怡！',NULL,NULL,NULL,NULL),(273,0,NULL,NULL,NULL,'关好门，$C。谁知道黑暗游侠什么时候会再次经过。',NULL,NULL,NULL,NULL),(278,0,NULL,NULL,NULL,'你好，好心的先生/女士。请坐，如果饿了就吃点东西。如果我忙于针线活，别担心——我在听着呢……',NULL,NULL,NULL,NULL),(288,0,NULL,NULL,NULL,'哈？！？哦。你看起来不像迪菲亚盗贼……也不像守夜人。可怜可怜我这个可怜人吧，好吗？',NULL,NULL,NULL,NULL),(289,0,NULL,NULL,NULL,'呃？你好，年轻的$C。你能穿过那些到处游荡的野兽找到这里来，真是个勇敢的家伙！$B$B既然你来了，也许你可以帮助一个老隐士……',NULL,NULL,NULL,NULL),(294,0,NULL,NULL,NULL,'向你致敬，旅行者。我的视力可能不太好，但我能在一英里外感觉到$c的脚步声。多年来我自豪地守卫着暴风城，但自从我的视力衰退后，我被迫退休了。',NULL,NULL,NULL,NULL),(313,0,NULL,NULL,NULL,'欢迎来到阿左拉之塔，年轻的$C。我是塞欧克瑞图斯。$B$B你找我有事？或者……也许是我有事找你？',NULL,NULL,NULL,NULL),(341,0,NULL,NULL,NULL,'我没时间闲聊，$N。我得赶在下雨之前把这座桥重建好。我完成的每个项目都按时且在预算之内，我可不想现在开始落后。',NULL,NULL,NULL,NULL),(342,0,NULL,NULL,NULL,'向你致敬，$N！欢迎来到我简陋的花园。最近的天气好极了。希望它能保持稳定，让我们有个好收成。',NULL,NULL,NULL,NULL),(344,0,NULL,NULL,NULL,'站在暴风王国湖畔镇法庭前的是哪位$c？说出你在这个镇子里的来意，$R。兽人对王国的威胁太严重了，没时间浪费在闲谈上。',NULL,NULL,NULL,NULL),(381,0,NULL,NULL,NULL,'幸会，$C。如果你是来谈生意的，那就给自己倒杯酒，我们好好聊聊。',NULL,NULL,NULL,NULL),(382,0,NULL,NULL,NULL,'我没时间闲聊，市民，但如果你愿意帮我们对抗兽人，那我就能给你找点事做。',NULL,NULL,NULL,NULL),(392,0,NULL,NULL,NULL,'不要惊慌，$r。我早已离开了这片土地，但我无意伤害你的种族。我一生中已经见证了太多的死亡。我现在唯一的愿望就是和平。也许你可以帮助我实现这个愿望。',NULL,NULL,NULL,NULL),(415,0,NULL,NULL,NULL,'嘿，哥们/女士，你能帮我个忙吗？我现在真的是走投无路了……',NULL,NULL,NULL,NULL),(464,0,NULL,NULL,NULL,'向你致敬，$C。现在时局艰难，我的朋友，我们的城镇被围攻了！黑石兽人从石头守望堡发动攻击，影皮潜伏在伊尔加拉之塔上空，赤脊山豺狼人群体正在集结力量。我希望你不是来度假的……',NULL,NULL,NULL,NULL),(469,0,NULL,NULL,NULL,'你好，$c。如果你是库尔森上校的朋友，我会当场砍倒你！但如果你是来帮助我们的，那就洗耳恭听……',NULL,NULL,NULL,NULL),(633,0,NULL,NULL,NULL,'黑暗的时代已经降临，$c……我们很快就会失去一切……当圣光抛弃所有不走在圣光之下的灵魂之时。',NULL,NULL,NULL,NULL),(656,0,NULL,NULL,NULL,'到处都是盗贼！$b$b太可怕了。洞穴坍塌在我们身上。我想矿业公司的人都死了，包括我的兄弟，那个工头。',NULL,NULL,NULL,NULL),(663,0,NULL,NULL,NULL,'卡文家族为了圣光的胜利而战。我在圣光下的职责是为他们对亡灵的战斗献出生命。卡文主人交给我消灭暮色森林中可恶的狼人的任务。也许你愿意帮助我？',NULL,NULL,NULL,NULL),(714,0,NULL,NULL,NULL,'你好，$c！打猎的好天气，你说呢？我自己猎野猪的运气还不错。也许你也想试试？',NULL,NULL,NULL,NULL),(715,0,NULL,NULL,NULL,'又是丛林中的美好一天！我能感觉到，这将是一次精彩的狩猎。等巴尼尔擦完枪，我就带着狩猎队深入藤蔓缠绕的密林。对一个老退伍兵来说，这退休生活还不错，嗯？',NULL,NULL,NULL,NULL),(733,0,NULL,NULL,NULL,'你在这儿走路小心点，小伙子/姑娘。你可能不是我们团队的人，但这并不意味着如果你越界了，我不会用拐杖揍你！',NULL,NULL,NULL,NULL),(737,0,NULL,NULL,NULL,'嗯，你好啊。你看起来不像是会拒绝赚点钱的人，嗯？我从你的眼神里就能看出来。我是摩格尔·凯伯克，艾泽拉斯业务的监督者，如果你想要财富，也许我可以安排一下。',NULL,NULL,NULL,NULL),(773,0,NULL,NULL,NULL,'$C，嗯？我是克拉赛克，瑞维尔加兹男爵的秘书。我对这片丛林里里外外的一切都了如指掌。也许你有兴趣知道棘齿城的石油最新价格？不？想找工作？我可以在这方面帮你。',NULL,NULL,NULL,NULL),(786,0,NULL,NULL,NULL,'你好，小伙子/姑娘。我是格瑞林·白须。我来这里调查寒脊山谷中日益增长的巨魔威胁。我发现了什么？有点麻烦……',NULL,NULL,NULL,NULL),(823,0,NULL,NULL,NULL,'你好，$c。通常我会在外面巡逻，照看暴风城的居民，但很多暴风城卫兵正在其他地方作战。所以我在这里，被委任为代理警长并悬赏缉拿罪犯，而我更愿意去巡逻……',NULL,NULL,NULL,NULL),(900,0,NULL,NULL,NULL,'什么风把你吹到湖畔镇法庭和尊敬的所罗门镇长面前来了？',NULL,NULL,NULL,NULL),(1071,0,NULL,NULL,NULL,'如果说时间教会了我一件事，那就是没有一项任务是枯燥的。守卫萨多尔大桥本应是一项轻松的任务。但联盟军队的主力都在别处作战，我们在这里寡不敌众，丹莫德已经失守了。',NULL,NULL,NULL,NULL),(1105,0,NULL,NULL,NULL,'你知道，我一直想成为一名勘探者，但我天生对数字敏感，协会认为我最适合做账目！学习，学习，我的青年时代每天都在学习……',NULL,NULL,NULL,NULL),(1139,0,NULL,NULL,NULL,'嗯，你好啊，市民。我是布朗特诺斯，准确地说，是布朗特诺斯镇长。我负责监督塞尔萨玛的民生，相信我，我们这里总是需要多一些强壮的臂膀！',NULL,NULL,NULL,NULL),(1141,0,NULL,NULL,NULL,'如果你是为了食物而来，那么欢迎！在整个暴风城……乃至整个艾泽拉斯，你都找不到比这更高档的餐厅了！$B$B如果你有其他事情，请长话短说。我有十几道菜在准备中，每道都需要精心照料。',NULL,NULL,NULL,NULL),(1217,0,NULL,NULL,NULL,'哼！好像我在这泥泞中要做的事情还不够多似的，还要应付所有这些分心的事！',NULL,NULL,NULL,NULL),(1239,0,NULL,NULL,NULL,'如果你愿意听那些让你心惊胆战、魂飞魄散的故事，那就给自己倒杯酒，坐下来听一段……',NULL,NULL,NULL,NULL),(1254,0,NULL,NULL,NULL,'穴居怪！我发誓众神把它们放在这片土地上只是为了折磨我！向矿井深处挖四英寸，然后被穴居怪逼退两英尺！',NULL,NULL,NULL,NULL),(1267,0,NULL,NULL,NULL,'欢迎来到雷霆麦酒酿酒厂，由我亲爱的老爹阿基勒斯·雷霆麦酒创立。自从我哥哥格瑞姆布兹在几个收获前醉醺醺地失踪后，我就一直维持着这里的运营。',NULL,NULL,NULL,NULL),(1284,0,NULL,NULL,NULL,'我祝福你，$c，我祈求这祝福能在这些艰难时期指引和保护你。保持警惕，但要对和平保持希望，因为希望是我们对抗黑暗的最强武器。',NULL,NULL,NULL,NULL),(1343,0,NULL,NULL,NULL,'哦，这不是一位朝气蓬勃的年轻$c吗，无疑是被我在战场上的功绩传说吸引来的！$B$B现在没时间讲故事了，因为有伟大而重要的事情等着去做！所以，如果你在寻找荣耀，今天幸运女神在对你微笑……',NULL,NULL,NULL,NULL),(1344,0,NULL,NULL,NULL,'虽然我们在这些废墟中正经历一段进展缓慢的时期，但我相信这不会持续太久。与此同时，我可以利用像你这样的人。你愿意帮助矮人探险者协会吗？',NULL,NULL,NULL,NULL),(1356,0,NULL,NULL,NULL,'我正在执行一项非常重要的任务。勘探者的事务。除非你有同样重要的事情要说，否则请原谅我。',NULL,NULL,NULL,NULL),(1374,0,NULL,NULL,NULL,'该死的酿酒师协会！他们能用上所有最好的原料，而我们却只能在这里凑合着找谷物和啤酒花！$B$B我真想给他们点苦头尝尝……',NULL,NULL,NULL,NULL),(1377,0,NULL,NULL,NULL,'驾驶蒸汽坦克不是每个人都能做到的。需要钢铁般的握力和钢铁般的神经……幸运的是我两者兼备！你呢？你的勇气如何？想向我证明一下吗？',NULL,NULL,NULL,NULL),(1440,0,NULL,NULL,NULL,'你找不到比暴风城皇家图书馆更丰富的知识宝库了！',NULL,NULL,NULL,NULL),(1495,0,NULL,NULL,NULL,'你好，$C。往东前往亡灵壁垒时要小心。最近的侦察报告显示该地区天灾活动有所增加，所以要格外谨慎。',NULL,NULL,NULL,NULL),(1499,0,NULL,NULL,NULL,'啊，你来了！我有任务要交给你，我不需要浪费时间解释它们的重要性。仔细听好。',NULL,NULL,NULL,NULL),(1500,0,NULL,NULL,NULL,'希望你还好，考虑到所有情况。$B$B坐下来，听我讲个故事。当然，这是个悲剧，但我希望最终能以复仇结束！',NULL,NULL,NULL,NULL),(1515,0,NULL,NULL,NULL,'血色十字军正在侵犯我们的家园。那些愚蠢的狂热者没有意识到，黑暗女士的忠诚仆人会让他们灭亡。',NULL,NULL,NULL,NULL),(1518,0,NULL,NULL,NULL,'黑暗女士已经发出了挑战。现在轮到我们去迎接它了。',NULL,NULL,NULL,NULL),(1646,0,NULL,NULL,NULL,'你好，我是巴洛斯·艾利克斯顿，暴风城的城市建筑师。',NULL,NULL,NULL,NULL),(1719,0,NULL,NULL,NULL,'这边，你这个没用的东西……！如果你想做点有用的事，就快点听好！',NULL,NULL,NULL,NULL),(1740,1,NULL,NULL,NULL,'这堆卷轴包含各种后勤和战略信息，以及加密的通信文件。',NULL,NULL,NULL,NULL),(1748,0,NULL,NULL,NULL,'我是伯瓦尔·弗塔根，暴风城大领主。',NULL,NULL,NULL,NULL),(1776,0,NULL,NULL,NULL,'我们在战斗中度过了一生中的太多时光，和平岁月的记忆变得越来越遥远。',NULL,NULL,NULL,NULL),(1937,0,NULL,NULL,NULL,'黑暗女士已经发出了挑战。现在轮到皇家药剂师协会来研制新的瘟疫了。我们将让阿尔萨斯和他那可恶的军队屈服。',NULL,NULL,NULL,NULL),(1938,0,NULL,NULL,NULL,'肯瑞托没有理会我的警告！联盟就是个骗局。阿鲁高是个鲁莽的傻瓜。',NULL,NULL,NULL,NULL),(1950,0,NULL,NULL,NULL,'我和我的兄弟正在执行侦察任务，但我们被困在这座农舍里。亡语者需要你的帮助！',NULL,NULL,NULL,NULL),(1952,0,NULL,NULL,NULL,'你好，$c。如果你在这里，那你一定知道银松森林遍布了我们的敌人。为了生存，被遗忘者必须击退他们！',NULL,NULL,NULL,NULL),(1977,0,NULL,NULL,NULL,'我接受的教育和培养是为了公共服务。人民的代表。我的技能不在于武器或工艺，而在于言辞和说服。',NULL,NULL,NULL,NULL),(2055,0,NULL,NULL,NULL,'皇家药剂师协会将响应黑暗女士的号召，揭开新瘟疫的秘密，彻底将阿尔萨斯和他那异端的天灾军团从这个世界上驱逐出去。',NULL,NULL,NULL,NULL),(2076,1,NULL,NULL,NULL,'这个锅中翻滚着浓稠的绿色气泡。未知生物的骷髅、骨头和器官在其粘稠的液体中游动……$B$B而懒洋洋地浮上来的，是曾经强大的两个巨魔的头颅：$B$B甘祖拉恩和奈兹利奥克。',NULL,NULL,NULL,NULL),(2080,0,NULL,NULL,NULL,'泰达希尔的创造是一项伟大的成就，但现在世界必须重新找回平衡。',NULL,NULL,NULL,NULL),(2083,0,NULL,NULL,NULL,'就像泰达希尔本身一样，多兰纳尔拥抱那些拥抱大地的人。',NULL,NULL,NULL,NULL),(2092,0,NULL,NULL,NULL,'攻城器械是每一位驾驶员的骄傲！',NULL,NULL,NULL,NULL),(2094,0,NULL,NULL,NULL,'你好，$c。我现在有点困难，皮革存货非常少了。',NULL,NULL,NULL,NULL),(2121,0,NULL,NULL,NULL,'情报……通过我们的侦察兵和特工，我们控制着洛丹伦的信息流动。天灾的动向，他们的据点，尽在我们的监视之下……',NULL,NULL,NULL,NULL),(2151,0,NULL,NULL,NULL,'向你致敬，$C。我们美丽森林的道路并非毫无危险。小心前行。',NULL,NULL,NULL,NULL),(2215,0,NULL,NULL,NULL,'为了服务于黑暗女士和瓦里玛萨斯，我们需要推进对抗人类 infestation 的前线。',NULL,NULL,NULL,NULL),(2216,0,NULL,NULL,NULL,'我们离研制出黑暗女士如此热切渴望的新瘟疫只有一步之遥了。',NULL,NULL,NULL,NULL),(2229,0,NULL,NULL,NULL,'想想看，酋长出生长大的地方竟然如此之近。',NULL,NULL,NULL,NULL),(2263,0,NULL,NULL,NULL,'我希望你是来工作的，$C。我们有很多事要做，部落、辛迪加和食人魔可不会来帮我们。',NULL,NULL,NULL,NULL),(2276,0,NULL,NULL,NULL,'当我第一次被授予南海镇镇长头衔时，我为能在职业生涯早期获得这样的任命而感到荣幸。$B$B但现在我在这里，我想知道如果我在暴风城整理文件会不会更好。',NULL,NULL,NULL,NULL),(2277,0,NULL,NULL,NULL,'我有很多工作要做。你是来协助我研究的吗？',NULL,NULL,NULL,NULL),(2285,0,NULL,NULL,NULL,'我的家